package model;
import java.io.Serializable;import model.annotation.Id;import model.annotation.Positive;import exception.*;
public class Account implements Serializable,Comparable<Account> {private static final long serialVersionUID=1L;@Id private final String accountNumber;private final String ownerName;@Positive private long balance;private boolean active=true;public Account(String no,String owner,long opening){accountNumber=no;ownerName=owner;balance=opening;}public String getAccountNumber(){return accountNumber;}public String getOwnerName(){return ownerName;}public synchronized long getBalance(){return balance;}public boolean isActive(){return active;}public synchronized void deposit(long amount)throws InvalidAmountException{if(amount<=0)throw new InvalidAmountException();balance+=amount;}public synchronized void withdraw(long amount)throws BankException{if(amount<=0)throw new InvalidAmountException();if(amount>balance)throw new InsufficientFundsException(amount-balance);balance-=amount;}public double interestRate(){return 4.0;}public synchronized boolean canWithdraw(long amount){return amount>0&&amount<=balance;}@Override public int compareTo(Account other){return accountNumber.compareTo(other.accountNumber);}@Override public String toString(){return accountNumber+" | "+ownerName+" | Balance: "+getBalance();}}
